def translate(text, lang):



    translated = TRANSLATIONS.get(lang, {}).get(text.lower(), text)
    if text == translated:
        print("%s: %s" % (lang, text))
    return translated

def translate(text, lang):




    if "," in text:
        terms = text.split(",")
        translated_terms = [translate(term.strip(), lang) for term in terms]
        return ", ".join(translated_terms)

    translated = TRANSLATIONS.get(lang, {}).get(text.lower(), text)
    return translated

