            parent_len = len(str(parent_path._make_child_relpath('_'))) - 1
        paths = [parent_path._make_child_relpath('')]
        while paths:
            path = paths.pop()
            if match is None or match(str(path), parent_len):
                # Yield *directory* path that matches pattern (if any).
                yield path
