            except OSError:
                pass
            else:
                for entry in entries:
                    # Handle directory entry.
                    try:
                        if entry.is_dir(follow_symlinks=follow_symlinks):
                            # Recurse into this directory.
                            paths.append(path._make_child_direntry(entry))
                            continue
                    except OSError:
