def partial_bezier_points(points, a, b):



    if a == 1:
        return [points[-1]] * len(points)

    a_to_1 = np.array([
        bezier(points[i:])(a)
        for i in range(len(points))
    ])
    end_prop = (b - a) / (1. - a)
    return np.array([
        bezier(a_to_1[:i + 1])(end_prop)
        for i in range(len(points))
    ])

